package commitmentportfolio

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// Generated by the actual Python evaluator from visibly synthetic typed input.
// This is cross-language identity consistency, never evidence authentication.
func TestActualPythonIdentityUsesExistingGoHashForUnicodeHTMLAndNanoseconds(t *testing.T) {
	raw, e := os.ReadFile("testdata/python-id-unicode.json")
	if e != nil {
		t.Fatal(e)
	}
	var out Analysis
	if json.Unmarshal(raw, &out) != nil {
		t.Fatal("Python vector is not the typed result")
	}
	id := out.ID
	out.ID = ""
	if !shaPattern.MatchString(id) || Hash(out) != id {
		t.Fatal("actual Python identity differs from existing Go Hash")
	}
	if out.ObservedAt.Nanosecond() != 123456789 || len(out.Positions) != 1 || out.Positions[0].Position.PaymentOption == nil || !strings.Contains(*out.Positions[0].Position.PaymentOption, "<&> café 雲\u2028line\u2029end") {
		t.Fatal("identity fixture lost Unicode, HTML or precise time")
	}
}
